import {RULES} from './evolution.js';
import {ACTION_DURATIONS,SUBSTEPS,DECISION_COST,REPEAT_COST} from './action-timing.js';
import {v,p,a,table,details} from './guide-markup.js';
const done=Math.floor(ACTION_DURATIONS[8]/2);
export const GUIDE_ACTIONS_TEXT={
 'guide-actions-body':p(`Мир сначала определяет, какие действия физически возможны. Мозг оценивает только этот набор и выбирает действие. Выбор запускает процесс: его результат появится после нужного числа подшагов, если процесс дойдёт до завершения.`)
 +table('Что меняется при завершении',['Действие','Условие начала и результат'],[
 ['Движение','Выбранный сосед существует и не является водой. Житель переходит на него и поворачивает взгляд.'],
 ['Подобрать',`На текущем гексе есть пища, а в инвентаре меньше ${v(RULES.inventoryCapacity,'порций')}. Одна порция переносится с гекса в инвентарь.`],
 ['Съесть',`В инвентаре есть порция, в желудке хватает места для ${v(RULES.foodEnergy,'энергии')}. Порция переходит в желудок; энергия тела пополняется при дальнейшем усвоении.`],
 ['Покой','Остаётся на текущем месте без процесса и фиктивного завершения. Усвоение, физический расход и проверки диспетчера продолжаются.'],
 ['Родить',`Достигнуты ${a('selection','пороги родов')}, интервал и условия населения. При успешном завершении появляется ребёнок.`],
 ['Положить',`В инвентаре есть порция, текущая клетка сухая и содержит меньше ${v(RULES.groundFoodCapacity,'порций')}. Одна порция переносится из инвентаря на гекс.`],
 ])
 +p(`Например, движение длится ${v(ACTION_DURATIONS[0]/SUBSTEPS,'Т')}. После ${v(done,'подшагов')} диспетчер запрашивает пересмотр: продолжение сохраняет прогресс движения, а выбор покоя прекращает его. В покое нет отсчёта до следующего обязательного основного вызова.`)
 +details('Продолжение, отмена и физический срыв',
 p('Малая наследуемая сеть проверяет незавершённую обычную деятельность каждый подшаг. Положительный выход запрашивает основной мозг, но сам действие не выбирает. Основной мозг может сохранить текущий процесс или выбрать другой доступный. Продолжение сохраняет длительность, цель и прогресс; новая деятельность начинает отдельный процесс.')
 +table('Причины прекращения процесса',['Причина','Что происходит'],[
 ['Добровольная отмена','Основной мозг выбирает другой процесс при пересмотре.'],
 ['Физический срыв','Условия перестают выполняться. Например, конкурент забирает последнюю порцию до завершения сбора.'],
 ['Гибель','Незавершённая деятельность прекращается вместе с жизнью.'],
 ])
 +p('При любой отмене потраченные время и энергия не возвращаются. При сборе, еде и выкладывании ресурс переносится только при завершении. Движение тоже не даёт промежуточной позиции между гексами. На границе завершения физическая возможность проверяется повторно.')
 +p(`После завершения прежний процесс уже закончен. Выбор той же деятельности создаёт новый процесс; это повтор, а не продолжение. Его базовая ставка решения — ${v(REPEAT_COST,'энергии')} вместо ${v(DECISION_COST)}. При движении повтор сопоставляется по фактическому направлению перехода, а не только подписи команды.`)
 +p(`Пересмотр и решение после физического срыва используют обычную базовую ставку. Обе ставки масштабируются ${a('brain','вычислительной стоимостью мозга')}; при выполненном обучении добавляется его цена. Даже решение продолжить процесс требует вычислений.`)
 +p(`Роды нельзя добровольно отменить или заменить другим действием. Их стартовые возрастные, энергетические и другие пороги не проверяются заново как пороги старта; при завершении нужны живой родитель и энергия на ${v(RULES.birthCost)}. Гибель или недостаток этой суммы исключают рождение. Для родов нет обычного посекундного расхода деятельности: сумма списывается в конце.`))
 +p(`Связанные темы: ${a('time','порядок событий')}, ${a('geography','направления движения')}, ${a('food','путь пищи')}, ${a('research','счётчики действий и прерываний')}.`),
};
